scoreCategory(row){
 // The admissions workbook retained the former label in these two 2026 history rows.
 if(row.year===2026 && row.category==='文科' && ['山西','内蒙古'].includes(row.province))return '历史';
 return row.category;
}
function controlLineMetrics(line,category,reference){
 const subject=/^(历史|物理)(?:\+.+)?$/.exec(category)?.[1];
 const cutoff=reference?.[subject];
 const ordinary=scoreMetric('省控线',line);
 if(!Number.isFinite(cutoff))return ordinary;
 const title=`${subject}类特殊类型招生控制线 ${cutoff} 分，查看官方出处`;
 return `<div class="score-cutoffs">${ordinary}<a class="metric-special" href="${esc(reference.source)}" target="_blank" rel="noopener" title="${title}" aria-label="${title}"><span>特控线</span><strong>${cutoff}<small class="score-unit">分</small></strong></a></div>`;
}
function provinceCard(r,reference){
 const category=scoreCategory(r);
 const metrics=[['最低分',r.min],['最高分',r.max],['最低排位',r.rank],['最高排位','未提供'],['录取人数','未提供']];
 return `<article class="score-card"><h3>${esc(category)}</h3><div class="score-all">${metrics.map(([k,v])=>scoreMetric(k,v)).join('')}${controlLineMetrics(r.line,category,reference)}${scoreMetric('超省控线',r.over)}</div></article>`;

